"""Canva continuation: formula meaning, business use, and varied visual explanations.

Preserve 28 continuation positions so the paired workbook handoffs remain valid.
"""
from pathlib import Path
from html import escape as esc
import json,base64

ROOT=Path(__file__).parents[3]
OUT=ROOT/'outputs/m08-canva-revision'
OUT.mkdir(parents=True,exist_ok=True)
slides=[]
def money(x): return ('−' if x<0 else '')+f'${abs(x):,.2f}'
def formula(text,why):return f'<div class="formula"><strong>{text}</strong><p>{why}</p></div>'
def flow(left,right,arrow='→',label='One year · 6% simple interest'):
 return f'<div class="flow"><div><small>Today</small><b>{left}</b></div><div class="arrow"><strong>{arrow}</strong><span>{label}</span></div><div><small>Later</small><b>{right}</b></div></div>'
def split(a,b):return f'<div class="split"><div>{a}</div><div>{b}</div></div>'
def stamp(label,amount,explanation):return f'<div class="stamp"><span>{label}</span><b>{amount}</b><p>{explanation}</p></div>'
def photo(name,text):
 p=ROOT/'MATH/M08/img'/f'bus123-math-m08-l01-{name}.jpg'
 data=base64.b64encode(p.read_bytes()).decode()
 return f'<div class="photo-split"><div>{text}</div><figure><img src="data:image/jpeg;base64,{data}" alt="Illustrative business scene"/><figcaption>Fictional teaching case · AI-generated illustration</figcaption></figure></div>'
def note(title,lines):return f'<div class="note"><div class="note-top">MERIDIAN ADVISORY GROUP</div><h2>{title}</h2>'+''.join(f'<div class="note-line"><span>{a}</span><b>{b}</b></div>' for a,b in lines)+'</div>'
def terms(items):return '<div class="terms">'+''.join(f'<div><b>{a}</b><span>{b}</span></div>' for a,b in items)+'</div>'
def bar(label,value,maxval=1100,color='sage'):
 return f'<div class="bar-label">{label}</div><div class="bar-track"><div class="bar {color}" style="width:{100*value/maxval:.3f}%">{money(value)}</div></div>'
def add(title,lead,body,prompt,kind='explain',location='',notes=''):
 n=len(slides)+9
 slides.append(dict(number=n,title=title,lead=lead,body=body,prompt=prompt,kind=kind,location=location,notes=notes))

add('What will today’s money become?','Meridian can set aside $1,000 for one year at 6% simple interest.',photo('payment-timing',formula('FV = P × (1 + r × t)','P = starting principal · r = annual rate · t = years')+'<div class="factor"><div class="factor-part"><b>1</b><span>keep the original money</span></div><b>+</b><div class="factor-part"><b>r × t</b><span>add the return earned</span></div></div>'),'Use future value to plan a future balance or a loan repayment.','photo',notes='Explain the 1 before multiplying. It represents 100% of the original principal; rt is the additional fraction earned.')
add('Work backward from the interest earned','Meridian earned $60 at 6% over one year. How much was originally invested?', '<div class="machine"><div><b>?</b><span>starting principal</span></div><div class="machine-center">× 6% × 1 year<br><strong>→</strong></div><div><b>$60</b><span>interest only</span></div></div>'+formula('P = I ÷ (r × t)','$60 ÷ (0.06 × 1) = $1,000'),'Use this when the interest is known but the original investment is missing.','machine',notes='Distinguish interest I from total future value FV. Optional algebra: r=I/(P×t); t=I/(P×r).')
add('What would you pay today for $1,060 later?','Meridian is offered a $1,060 receipt in one year. Its comparable simple return is 6%.',flow('$1,000','$1,060','←','Undo the one-year growth')+formula('PV = FV ÷ (1 + r × t)','$1,060 ÷ 1.06 = $1,000 today'),'Discounting finds the starting money needed to produce a promised future amount.','timeline',notes='Explain division as reversing multiplication. A higher future receipt is not automatically a better offer.')
add('Try it: separate the money from its earnings','Use the $1,000, 6%, one-year example in your follow-along.', '<div class="balance-build"><div class="principal">Original money<br><b>$1,000</b></div><div class="plus">+</div><div class="unknown">Interest earned<br><b>?</b></div><div class="plus">=</div><div class="total">Ending balance<br><b>?</b></div></div>','Calculate interest first, then the whole balance. Why are these different amounts?','activity','Simple interest · C20:C21')
add('The original money does not disappear','A 6% return adds six cents for every dollar held for a full year.', '<div class="stack"><div class="stack-principal">Original principal · $1,000</div><div class="stack-interest">Interest · $60</div></div><div class="brace">Total after one year: <b>$1,060</b></div>'+formula('I = P × r × t','$1,000 × 0.06 × 1 = $60 interest'),'Future value = principal + interest. Quoting only $60 leaves out the original investment.','balance',notes='The small interest segment is proportional to the original principal. Connect the 6% rate to the size of the addition.')
add('Two questions can point to the same starting money','One starts with the earnings. The other starts with the entire future receipt.',split(stamp('You know the interest','$60','What principal earned it at 6% in one year?'),stamp('You know the total receipt','$1,060','What is the whole payment worth today?')),'Try both backward calculations. Choose the formula from what the question gives you.','activity','Simple interest · C22:C23')
add('Same answer, different information','Both calculations describe the same investment under the same simple-interest assumptions.', '<div class="routes"><div><small>Interest only</small><b>$60 ÷ 0.06</b></div><div class="route-arrow">↘</div><div class="destination"><b>$1,000</b><span>starting money</span></div><div><small>Total future value</small><b>$1,060 ÷ 1.06</b></div><div class="route-arrow">↗</div></div>','Never divide interest by the total growth factor, or divide the whole receipt by the interest rate alone.','routes')
add('Could a short loan solve a cash shortage?','Meridian borrows $18,500 for 8 months at 6.2% annual simple interest.',photo('payment-timing','<div class="scenario-question">What amount must be available on the repayment date?</div>'+terms([('8 ÷ 12','part of one year'),('Interest','the cost of using the money'),('Repayment','principal plus borrowing cost')])),'Build checkpoint B, then explain how much of the repayment is interest.','activity-photo','Live You Try It · G12:G14; explanation B31:G33')
add('Budget for the whole repayment','The annual rate applies to only eight months of borrowing.',note('Loan repayment summary',[('Principal borrowed','$18,500.00'),('Interest: $18,500 × 6.2% × 8/12','$764.67'),('Total due after 8 months','$19,264.67')]),'The borrowing cost is $764.67. The cash required at maturity is $19,264.67.','document')
add('Days are another way to describe the wait','Meridian’s short-term note runs for 80 actual days.',split(note('Note terms',[('Principal','$32,000'),('Annual simple rate','4.5%'),('Term','80 days'),('Stated year basis','365 days')]),formula('I = P × r × (days ÷ year basis)','80/365 is about 0.219 of a year.<br><br>$32,000 × 4.5% × 80/365 = <b>$315.62</b>')),'The contract’s year basis tells you how to convert the days before calculating interest.','document','Note example · B6')
add('Same loan. Same days. Two possible conventions.','Compare 75-day interest on $42,000 at a 4.8% annual rate.', '<div class="basis"><div><b>75</b><hr/><strong>365</strong><span>exact-interest basis</span></div><div class="basis-question">Which is the larger<br>fraction of a year?<br><b>?</b></div><div><b>75</b><hr/><strong>360</strong><span>ordinary-interest basis</span></div></div>','Predict which produces more interest. Then calculate checkpoint A and explain why.','activity','Live You Try It · G6:G10; explanation B26:G28')
add('A slightly larger year fraction means more interest','The annual rate, principal, and actual waiting period all stay the same.',split(stamp('365-day basis','$414.25','75/365 ≈ 0.205479 years'),stamp('360-day basis','$420.00','75/360 ≈ 0.208333 years'))+'<div class="difference">Difference for this loan: <b>$5.75</b></div>','Use the agreed convention. The two calculations differ because their denominators differ.','comparison')
add('Does the interest earn interest too?','Start with the same $1,000 and 6% annual rate. Now hold it for two years.', '<div class="growth-lanes"><div><h2>Simple interest</h2><div class="growth-path"><b>$1,000</b><span>+$60 →</span><b>$1,060</b><span>+$60 →</span><b>$1,120</b></div><p>Each year uses the original $1,000.</p></div><div><h2>Annual compounding</h2><div class="growth-path"><b>$1,000</b><span>+$60 →</span><b>$1,060</b><span>+$63.60 →</span><b>$1,123.60</b></div><p>Year 2 uses the whole $1,060 balance.</p></div></div>','The extra $3.60 is 6% earned on the prior $60 of interest.','growth',notes='Predict the second-year interest before explaining the second lane. Growth formulas are simple FV=P(1+rt) and compound FV=P(1+r)^t.')
add('The growth rule determines the discount rule','What is $1,120 received in two years worth today at 6%?', '<div class="model-fork"><div class="fork-top">How would money grow?</div><div class="fork-arrows">↙　　　　　　　　　↘</div><div class="fork-bottom"><div><h2>Simple</h2><b>÷ (1 + r × t)</b><p>Divide by 1.12<br><strong>$1,000.00 today</strong></p></div><div><h2>Annual compound</h2><b>÷ (1 + r)^t</b><p>Divide by 1.1236<br><strong>$996.80 today</strong></p></div></div></div>','Discounting reverses the stated growth process. It does not choose the process for you.','fork')
add('A negative PV can describe a valuable investment','From the investor’s viewpoint, money leaves today and comes back later.', '<div class="cash-direction"><div class="outflow"><span>PAY TODAY</span><b>−$996.80</b><p>cash leaving your account</p></div><div class="cash-arrow">→<small>6% annually<br>2 years</small></div><div class="inflow"><span>RECEIVE LATER</span><b>+$1,120</b><p>cash entering your account</p></div></div>'+formula('PV(rate, years, 0, future receipt)','The 0 means no recurring payments. A positive receipt gives a negative present outflow.'),'For comparing offers, show the positive magnitude with −PV(…). Keep the investor’s direction clear.','cash')
add('A good valuation makes the round trip','If today’s value is correct, growing it forward should recover the promised receipt.', '<div class="roundtrip"><div><b>$996.80</b><span>value today</span></div><div class="roundtrip-arrows"><strong>× 1.06² →</strong><p>grow forward</p><strong>← ÷ 1.06²</strong><p>discount backward</p></div><div><b>$1,120</b><span>receipt in two years</span></div></div>','Use the same rate, time, and model in both directions. Excel’s FV function provides the same check.','roundtrip')
add('What should Meridian pay for a future receipt?','A client offers $30,000 payable in two years. Meridian requires 6.5% annually.',photo('offer-comparison','<div class="scenario-question">Would paying $30,000 today leave any return for waiting?</div><div class="task-text">Value the future receipt today.<br><br>Then grow your value forward to check it.</div>'),'Build checkpoint C. Explain the cash-flow signs and what your verification confirms.','activity-photo','Live You Try It · G16:G18; explanation B36:G38')
cpv=30000/1.065**2
add('The discount creates room to earn the return','A smaller investment today can grow into the $30,000 future receipt.',flow(money(cpv),'$30,000','→','× 1.065² over two years')+formula('PV = $30,000 ÷ 1.065²',f'{money(cpv)} today grows to $30,000 under the stated annual compound model.'),'In Excel: the investment is a negative outflow; its comparison value is a positive magnitude.','timeline')
add('A 15-month wait is more than one annual period','Meridian expects $18,000 in 15 months at a 6% annual compound rate.', '<div class="ruler"><div class="ruler-year">12 months<br><b>1 year</b></div><div class="ruler-quarter">3 months<br><b>¼ year</b></div></div>'+formula('t = 15 ÷ 12 = 1.25 years','PV = $18,000 ÷ (1.06)^1.25 = $16,735.56'),'The exponent uses annual periods. This example assumes fractional-year annual compound discounting.','ruler','Present value · C23:C24')
def bars(items):
 return '<div class="bars">'+''.join(f'<div class="barrow"><span>{label}</span><div class="bar-track"><div class="bar steel" style="width:{v:.3f}%">{money(v)}</div></div></div>' for label,v in items)+'</div><div class="axis">Value today of the same $100 receipt · common $0–$100 scale</div>'
add('A longer wait means more discounting','At a fixed 6% annual rate, compare the same $100 received on three dates.',bars([(f'{t} year'+('s' if t>1 else ''),100/1.06**t) for t in [1,3,5]]),'Practical use: compare payment schedules. A later receipt must compensate you for waiting longer.','chart')
add('What return would make waiting worthwhile?','For $100 received in three years, a higher required return means a lower value today.',photo('discount-rate-meeting',terms([('4% → $88.90','lower required return'),('6% → $83.96','same three-year receipt'),('8% → $79.38','higher required return')])),'Practical use: ask whether the payment’s timing and risk justify the price you pay today.','photo',notes='Connect the required return to opportunity cost, purchasing power and payment risk without mechanically adding three percentages.')
heat='<div class="heatmap"><div></div>'+''.join(f'<div class="heat-head">{t} year'+('s' if t>1 else '')+'</div>' for t in [1,3,5])
for r in [.04,.06,.08]:
 heat+=f'<div class="heat-head">{r:.0%}</div>'
 for t in [1,3,5]:
  v=100/(1+r)**t;heat+=f'<div class="heat-cell" style="background:rgba(74,124,94,{.12+(v-65)/40*.55:.3f})">{money(v)}</div>'
heat+='</div>'
add('Find the most valuable corner','Value today of $100 received later. Across: change the wait. Down: change the required return.',heat,'Shortest wait + lowest rate gives the highest PV. Explain the pattern, then recreate it in the workbook.','heatmap','Present value · C30:E32')
add('Choose the model that matches the promise','Meridian expects $18,000 in two years at 6%. Which rule belongs in the denominator?', '<div class="model-choice"><div><h2>Simple growth</h2><strong>1 + r × t</strong><p>One addition based on original principal</p><b>$16,071.43 today</b></div><div><h2>Annual compounding</h2><strong>(1 + r)^t</strong><p>Multiply the growth factor each year</p><b>$16,019.94 today</b></div></div>','The challenge specifies annual compounding. Use that model consistently for every payment.','choice','Present value · C39:C40')
add('One future payment becomes one value today','Worked example: a $10,000 payment due at the end of year 2; required annual return 6%.', '<div class="payment-back"><div class="today-box"><small>TODAY</small><b>$8,899.96</b></div><div class="discount-arrow">←<span>divide by 1.06²</span></div><div class="receipt"><span>PAYMENT DUE</span><b>$10,000</b><small>End of year 2</small></div></div>'+formula('PV = Future payment ÷ (1 + r)^t','The exponent counts how many annual growth periods you must undo.'),'Practical use: value an invoice, contract payment, or other future receipt on today’s date.','receipt')
add('Which offer would you accept?','Meridian can choose $75,000 today or five future receipts. Use a 6% annual compound rate.',photo('offer-comparison','<div class="offer-now"><small>OFFER A · TODAY</small><b>$75,000</b></div><div class="mini-stream">OFFER B · END-OF-YEAR RECEIPTS<br><strong>$18k → $22k → $25k → $20k → $15k</strong><span>Year 1　　　 2　　　 3　　　 4　　　 5</span></div>'),'Value every receipt today before comparing. Build the challenge, then make and defend your choice.','activity-photo','Challenge · E12:E18; recommendation B19:E23')
payments=[18000,22000,25000,20000,15000]
converge='<div class="converge"><div class="converge-total"><span>ALL VALUES TODAY</span><b>$84,602.28</b><small>sum the unrounded values</small></div><div class="converge-lines">'
for t,v in enumerate(payments,1):converge+=f'<div class="discount-row">Year {t}: {money(v)} ÷ (1.06)^{t} = {money(v/1.06**t)}</div>'
converge+='</div></div>'
add('Different payment dates, one comparison date','Each receipt is discounted for its own waiting period.',converge,'Do not add future dollars first and discount them as if they all arrive together.','converge')
add('The payment stream has the higher value today','At the stated 6% rate, compare the two offers on the same date.', '<div class="offer-bars">'+bar('Offer A · cash today',75000,90000,'sage')+bar('Offer B · stream valued today',84602.281689,90000,'steel')+'</div><div class="advantage"><b>$9,602.28</b><span>additional value today from Offer B</span></div>','A higher required return or less reliable future payments could reverse the recommendation.','decision')
add('Use the formula to answer a business question','The model turns payment timing into a decision you can explain.', '<div class="decision-map"><div><span>Need the ending balance?</span><b>Grow forward →</b><p>Plan savings or a repayment.</p></div><div><span>Need a fair value today?</span><b>← Discount back</b><p>Price a future receipt.</p></div><div><span>Comparing offers?</span><b>Use one date</b><p>Then explain return, timing, and risk.</p></div></div>','Before calculating: identify the known amount, the unknown, the growth model, and the valuation date.','synthesis')
assert len(slides)==28

